import{_ as o,h as n,i as t,c as s,v as e,p as i,x as r,m,e as p,S as h}from"./chunks/framework.Dvtg8yj2.js";const A=JSON.parse('{"title":"Mamba","description":"","frontmatter":{"title":"Mamba","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mamba.md","filePath":"llm/mamba.md","lastUpdated":1788454257000}'),_={name:"llm/mamba.md"};function d(b,a,c,S,D,B){const l=n("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="mamba" tabindex="-1">Mamba <a class="header-anchor" href="#mamba" aria-label="Permalink to &quot;Mamba&quot;">​</a></h1><div class="epigraph"><p>把历史压进固定大小的状态，并让这段动力学随输入选择该记什么。</p><footer>Gu &amp; Dao，Mamba，2023</footer></div><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Transformer 的自注意力把过去写成一张键值表：每一步对所有先前位置做点积，训练和预训练期的计算随序列长度平方增长，推理时的 KV 缓存随长度线性增长。长上下文、长音频、百万级 token 的扫描，都会先撞上这张表，而不是先撞上模型容量。</p><p>状态空间模型（SSM）走另一条路。连续时间里它写成</p> \\[h&#39;(t) = A h(t) + B x(t),\\qquad y(t) = C h(t), \\]<p>离散化之后每一步只拿当前输入更新一份固定大小的隐状态。序列再长，状态宽度也不涨，解码是常数状态、线性时间。S4 及其对角化变体已经证明：只要 \\(A\\) 的结构选对（HiPPO 一类的长程记忆先验），线性 SSM 可以在长程依赖上接近注意力。</p><p>缺的是选择。线性时不变的 SSM 对所有 token 用同一套 \\((\\Delta, B, C)\\)。它无法按内容决定「这个 token 该写入状态还是该被滤掉」。语言模型的关键操作——忽略噪声、记住一个变量名、在几百步之后把它取回来——恰恰要求内容相关的记忆。注意力用 softmax 门控做到了这一点；当时的 SSM 做不到。Mamba 的问题因此非常具体：在保住线性时间和常数状态的前提下，给 SSM 装上随输入变化的选择。<span class="marginnote">选择发生在时间尺度 \\(\\Delta\\) 上，不是另做一次 softmax。状态宽度仍与长度无关。</span></p><h3 id="时不变-ssm-记不住该忘的东西" tabindex="-1">时不变 SSM 记不住该忘的东西 <a class="header-anchor" href="#时不变-ssm-记不住该忘的东西" aria-label="Permalink to &quot;时不变 SSM 记不住该忘的东西&quot;">​</a></h3><p>S4 把 \\(A\\) 做成结构化、可对角化的矩阵，把卷积核预计算出来，训练时当长卷积用。它对均匀采样的信号（音频、物理轨迹）很合适，对离散、语义稀疏的语言并不合适。语言里绝大多数 token 不该进长期状态；极少数 token 必须几乎无损地活过整个上下文。固定 \\(\\Delta\\) 给出固定的时间尺度，做不到这种门控。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Mamba 的方法是<strong>选择性 SSM</strong>：让离散步长 \\(\\Delta\\)、输入矩阵 \\(B\\) 和输出矩阵 \\(C\\) 都成为当前输入 \\(x_t\\) 的函数，同时把 \\(A\\) 保持为与输入无关的结构化参数。选择发生在时间尺度上，而不是另起一套注意力。</p><h3 id="输入门控的" tabindex="-1">输入门控的 \\(\\Delta\\) <a class="header-anchor" href="#输入门控的" aria-label="Permalink to &quot;输入门控的 $\\Delta$&quot;">​</a></h3><p>离散化把连续系统变成</p> \\[\\bar A = \\exp(\\Delta A),\\qquad \\bar B = (\\Delta A)^{-1}\\bigl(\\exp(\\Delta A)-I\\bigr)\\,\\Delta B. \\]<p>\\(\\Delta\\) 是步长。\\(\\Delta\\) 大，状态被当前输入强烈改写，接近「重置」；\\(\\Delta\\) 小，状态几乎沿 \\(A\\) 的衰减滑过去，接近「跳过」。Mamba 用一层线性映射加非线性把 \\(\\Delta_t\\) 从 \\(x_t\\) 里读出来：</p> \\[\\Delta_t = \\tau\\bigl(W_\\Delta x_t\\bigr), \\]<p>其中 \\(\\tau\\) 是 softplus 一类保证正步长的函数。\\(B_t\\)、\\(C_t\\) 同样由 \\(x_t\\) 线性得到。于是每一步的离散系统 \\((\\bar A_t, \\bar B_t, \\bar C_t)\\) 都随内容而变。这就是「随输入门控 \\(\\Delta\\)」：门不在 softmax 上，而在 SSM 的时间常数上。</p><p>\\(A\\) 仍是对角或分块对角的可学习参数，不随 \\(t\\) 变。把 \\(A\\) 也做成输入相关会破坏扫描的结构化，也没有被证明有必要。选择集中在 \\(\\Delta, B, C\\) 上，是容量和可实现性之间的切口。<span class="marginnote">\\(\\Delta\\) 大则当前输入改写状态，\\(\\Delta\\) 小则跳过。门控的是步长，不是注意力权重。</span></p><h3 id="不再写成卷积" tabindex="-1">不再写成卷积 <a class="header-anchor" href="#不再写成卷积" aria-label="Permalink to &quot;不再写成卷积&quot;">​</a></h3><p>时不变 SSM 等价于一条与输入无关的卷积核，可以 FFT。一旦 \\(\\Delta_t, B_t\\) 随 \\(t\\) 变，卷积核不再共享，FFT 路径断了。剩下的算法是<strong>线性扫描</strong>：</p> \\[h_t = \\bar A_t h_{t-1} + \\bar B_t x_t,\\qquad y_t = C_t h_t. \\]<p>扫描是串行的，但每步是矩阵–向量，状态宽度与序列长度无关。这正是用选择换掉卷积加速之后，必须重新设计的计算图。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="硬件感知扫描" tabindex="-1">硬件感知扫描 <a class="header-anchor" href="#硬件感知扫描" aria-label="Permalink to &quot;硬件感知扫描&quot;">​</a></h3><p>朴素扫描会把形状为 \\((B, L, D, N)\\) 的完整状态写进 HBM，带宽先炸。Mamba 的实现把扫描做在 SRAM 里：按块读入 \\((x, \\Delta, B, C)\\)，在片上完成离散化与扫描，只把 \\(y\\) 写回。中间状态不落全局内存。这不是新的数值方法，是把 SSM 的常数状态优势真的映射到 GPU 的存储层次上。没有这一步，选择性 SSM 在墙上时钟上打不过注意力的 FlashAttention。<span class="marginnote">线性时间是算法复杂度；墙上时钟还取决于是否把状态留在片上。两者经常被混为一谈。</span></p><p>训练仍是 \\(O(LDN)\\)，对长度 \\(L\\) 线性；推理时每生成一个 token 只更新一份状态，KV 缓存不随已生成长度增长。状态大小是 \\(D \\times N\\)（模型宽 × SSM 状态宽），与上下文长度脱钩。</p>',27)),(t(),i(h,null,{default:r(()=>[p(l,{id:"mermaid-71",class:"mermaid",graph:"flowchart%20LR%0A%20%20X%5B%22%E8%BE%93%E5%85%A5%20x_t%22%5D%20--%3E%20Sel%5B%22%E7%BA%BF%E6%80%A7%E6%98%A0%E5%B0%84%E5%BE%97%E5%88%B0%20%CE%94_t%2C%20B_t%2C%20C_t%22%5D%0A%20%20Sel%20--%3E%20Disc%5B%22%E7%94%A8%20%CE%94_t%20%E7%A6%BB%E6%95%A3%E5%8C%96%20A%2C%20B%22%5D%0A%20%20Disc%20--%3E%20Scan%5B%22%E7%89%87%E4%B8%8A%E6%89%AB%E6%8F%8F%E6%9B%B4%E6%96%B0%20h_t%22%5D%0A%20%20Scan%20--%3E%20Y%5B%22%E8%BE%93%E5%87%BA%20y_t%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="选择在语言模型里做什么" tabindex="-1">选择在语言模型里做什么 <a class="header-anchor" href="#选择在语言模型里做什么" aria-label="Permalink to &quot;选择在语言模型里做什么&quot;">​</a></h3><p>门控 \\(\\Delta\\) 的经验图像是：空格、标点、低信息 token 对应很小的 \\(\\Delta\\)，状态几乎不更新；罕见专名、括号配对、需要长程拷贝的 token 对应大 \\(\\Delta\\)，被写进状态。\\(B_t\\) 决定写入方向，\\(C_t\\) 决定读出。这与注意力的「对哪些键分配质量」同类，但压缩进了固定宽度的状态，而不是保留全部键值。</p><p>代价立刻清楚：状态是有损压缩。需要精确拷贝很长一段原文、或在上下文里做任意位置的 associative recall 时，固定宽度会丢细节。Mamba 用较大的 \\(N\\) 和更深的堆叠缓解，但不能在信息论上等价于全量 KV。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>Mamba 解决的是<strong>序列层的复杂度形态</strong>，不是语言模型的全部。它在信息密集、需要精确检索的任务上，仍可能输给同规模的 Transformer。工程上常见的取舍包括：状态宽 \\(N\\) 与通道宽 \\(D\\) 的乘积决定显存，不能无代价加大；扫描的并行度不如 GEMM，短序列上未必更快；与 MoE、局部注意力混用时，收益来自「把全局精确检索留给少数注意力层」，而不是 SSM 单层取代一切。</p><p>实现层面，离散化的数值要稳定，\\(\\Delta\\) 的下界不能到零，否则梯度消失。推理时状态必须和训练时同一套离散化，否则长生成会漂。这些是把论文里的扫描变成可训练层时就会碰到的细节，不是架构之外的附录。</p><p>另一条边界是评测口径。线性时间只在足够长的 \\(L\\) 上相对注意力有意义；短上下文、大 batch 的训练，瓶颈往往在 MLP 和通信，不在注意力。用 Mamba 替换 Transformer，要先问上下文是否真的长、KV 是否真的是墙。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>Mamba（Gu &amp; Dao，2023）给 SSM 装上随输入变化的 \\(\\Delta, B, C\\)，用内容选择代替时不变卷积，再用硬件感知扫描保住线性时间和常数状态。它把「该记什么」从 softmax 搬到了时间尺度上；它没有把精确的随机访问搬进固定宽度的状态。后续的 Mamba-2、Griffin、Jamba，都是在这条选择与压缩的轴上继续切，而不是回到二次注意力本身。</p>',9))])}const M=o(_,[["render",d]]);export{A as __pageData,M as default};
